// Read-only linkage to the retained Japanese Master Index final resolution; not an admission or DB write.
import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import assert from 'node:assert/strict';
const base=process.cwd(),manifest=JSON.parse(fs.readFileSync(base+'/docs/audits/japanese_master_index_v4/final/jpn_master_resolved_card_identities_v1.json')),review=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/evidence-review-20261119.json')),snapshot=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/jpn-dp4-review-readback-20261119.json'));const ids=new Set(snapshot.parents.map(x=>x.record.id));assert.equal(ids.size,136);const rows=[];for(const file of manifest.content.dataset.shard_paths){const shard=JSON.parse(gunzipSync(fs.readFileSync(base+'/'+file)));for(const r of shard.content.rows)if(ids.has(r.existing_card_print_id))rows.push({id:r.existing_card_print_id,gv_id:r.existing_gv_id,admission_status:r.admission_status,final_disposition:r.final_disposition,conflict_status:r.conflict_status,disposition_reasons:r.disposition_reasons,evidence_status:r.evidence_status,source_families:r.independent_source_families,identity_key:r.jpn_card_identity_key??null});}const group=review.candidates.reduce((m,x)=>(m.add(x.card_print_id),m),new Set()),counts={};for(const r of rows){let k=(group.has(r.id)?'candidate':'other')+'|'+r.final_disposition;counts[k]=(counts[k]??0)+1}const found=new Set(rows.map(r=>r.id)),out={generated_at:new Date().toISOString(),scope:'Retained October 22 Master Index V4 resolution, not a fresh adjudication or authorization to update.',master_manifest:base+'/docs/audits/japanese_master_index_v4/final/jpn_master_resolved_card_identities_v1.json',master_fingerprint:manifest.content.dataset.content_fingerprint_sha256,target_parents:ids.size,resolution_rows:rows.length,parents_found:found.size,missing_ids:[...ids].filter(x=>!found.has(x)),counts,rows};fs.writeFileSync('docs/audits/jpn_dp4_artist_review_20261119/master-index-resolution-review-20261119.json',JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({target_parents:ids.size,resolution_rows:rows.length,parents_found:found.size,missing:out.missing_ids.length,counts}));
